#include <iostream>
#include <algorithm>
using namespace std;

using ll = long long;

const int nmax = 100005;
ll a[nmax];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    for (int i = 0; i < n; ++i)
        cin >> a[i];

    sort(a + 1, a + n);

    ll res = 0;
    ll cnt = 0;

    for (int j = 1; j < n; ++j) {
        if (a[j] >= a[0]) {
            res += a[j] - a[0];
            ++cnt;
        }
    }

    if (cnt == 0) {
        cout << 0 << '\n';
    } else {
        cout << (res - cnt + 1) / cnt << '\n';
    }

    return 0;
}

